/* --- SOURCE: keys-calc.js --- */
/**
 * KEYS & STRAIGHT-SIDED SPLINES CALCULATION ENGINE
 * MITCalc 1.74 ShaftCon_01.xlsb Independent Port
 * Standards: DIN 6885, ISO 2491, ISO R773, ANSI B17.1, BS 4235, BS 46, JIS B 1301, CSN 02 2562
 *            DIN 6888, ISO 3912, ANSI B17.2, BS 6, CSN 30 1385
 *            ISO 14, DIN 5464, DIN 5471, DIN 5472, CSN 01 4942, SAE J499 / J501
 * Zero-Force Scope Protocol: 100% Geometry, Dimensions, Tolerances & CAD.
 * Zero-Tolerance Policy: Delta = 0.000000
 */

const KeysCalc = {
  /**
   * Tính toán Then Bằng (Parallel Side Keys)
   * @param {Object} params - { units, keyTypeIndex, numKeys, shaftDiam, chosenLength, fitClass }
   */
  calculateParallelKey(params) {
    const isMetric = params.units !== 'imperial';
    const typeIdx = Math.max(0, Math.min(10, params.keyTypeIndex || 0));
    const numKeys = Math.max(1, Math.min(4, parseInt(params.numKeys, 10) || 1));
    const d = parseFloat(params.shaftDiam) || (isMetric ? 40.0 : 1.5);
    const fitClass = params.fitClass || 'normal'; // 'tight' (P9), 'normal' (N9), 'sliding' (JS9)

    const meta = KEYS_DATABASE.T_Key1_Name[typeIdx];
    const tabName = meta[1];
    const tabRatio = isMetric ? parseFloat(meta[2]) : parseFloat(meta[3]);
    const isCalcDepth = parseInt(meta[8], 10) === 1; // 1 for ANSI chordal formula, 0 for tabular depth
    const table = KEYS_DATABASE[tabName];

    // Find suitable row in table based on shaft diameter d
    let selectedRow = null;
    let rowIndex = -1;
    for (let i = 0; i < table.length; i++) {
      const row = table[i];
      const dMin = parseFloat(row[1]) * tabRatio;
      const dMax = parseFloat(row[2]) * tabRatio;
      // First row checks >= dMin, others check > dMin
      const inRange = (i === 0) ? (d >= dMin && d <= dMax) : (d > dMin && d <= dMax);
      if (inRange) {
        selectedRow = row;
        rowIndex = i;
        break;
      }
    }

    // Fallback if out of bounds: clamp to nearest row
    if (!selectedRow) {
      if (d < parseFloat(table[0][1]) * tabRatio) {
        selectedRow = table[0];
        rowIndex = 0;
      } else {
        selectedRow = table[table.length - 1];
        rowIndex = table.length - 1;
      }
    }

    const keyName = selectedRow[0];
    const b = parseFloat(selectedRow[3]) * tabRatio;
    const h = parseFloat(selectedRow[4]) * tabRatio;
    const Lmin_tab = parseFloat(selectedRow[5]) * tabRatio;
    const Lmax_tab = parseFloat(selectedRow[6]) * tabRatio;
    const chamfer_s = parseFloat(selectedRow[7]) * tabRatio;
    const R_head = b / 2.0;

    // Shaft keyway depth t (t1)
    let t1 = 0;
    if (isCalcDepth) {
      // ANSI chordal formula: t1 = (d - sqrt(d^2 - b^2) + h) / 2
      const diff = d * d - b * b;
      t1 = (d - Math.sqrt(Math.max(0, diff)) + h) / 2.0;
    } else {
      t1 = parseFloat(selectedRow[8]) * tabRatio;
    }

    // Rounding per units
    const rndDec = isMetric ? 2 : 4;
    t1 = Math.round(t1 * Math.pow(10, rndDec)) / Math.pow(10, rndDec);

    // Remaining shaft diameter d1 at groove root
    const d1 = numKeys === 1 ? (d - t1) : (d - 2 * t1);

    // Hub keyway depth t2
    let t2 = 0;
    if (isCalcDepth) {
      // ANSI: t2 = h - t1
      t2 = h - t1;
    } else {
      // ISO/DIN standard hub depth:
      // In DIN 6885: t2 = h - t1 + clearance (or standard t2 table)
      // Usually t2 = h - t1 + (isMetric ? 0.2 : 0.008)
      t2 = h - t1 + (isMetric ? (d <= 50 ? 0.3 : 0.4) : 0.012);
    }
    t2 = Math.round(t2 * Math.pow(10, rndDec)) / Math.pow(10, rndDec);

    // Hub inner diameter at groove peak d2
    const d2 = numKeys === 1 ? (d + t2) : (d + 2 * t2);

    // Standard available lengths from length table
    const lenTabName = isMetric ? meta[4] : meta[5];
    const lenTable = KEYS_DATABASE[lenTabName] || [];
    const availableLengths = lenTable.map(row => parseFloat(Array.isArray(row) ? row[0] : row));

    // Filter available lengths for this key
    const validLengths = availableLengths.filter(l => l >= Lmin_tab * 0.99 && l <= Lmax_tab * 1.01);

    // Chosen length L
    let chosenL = parseFloat(params.chosenLength);
    if (!chosenL || isNaN(chosenL)) {
      // Pick a reasonable standard length in middle of valid range
      chosenL = validLengths.length > 0 ? validLengths[Math.floor(validLengths.length / 2)] : (Lmin_tab + Lmax_tab) / 2;
    }

    // Functional length Lf
    // Form A (round ends): Lf = L - 2 * R = L - b
    // Form B (square ends): Lf = L
    const Lf_formA = Math.max(0, chosenL - b);
    const Lf_formB = chosenL;

    // Tolerances (ISO 286 / DIN 6885)
    const tolerances = this.getParallelKeyTolerances(b, h, isMetric, fitClass);

    return {
      typeIdx,
      typeName: meta[0],
      tabName,
      rowIndex,
      keyName,
      d,
      numKeys,
      b,
      h,
      t1,
      t2,
      d1,
      d2,
      R_head,
      chamfer_s,
      Lmin_tab,
      Lmax_tab,
      chosenL,
      Lf_formA,
      Lf_formB,
      validLengths,
      availableLengths,
      tolerances,
      isMetric
    };
  },

  /**
   * Tính toán Dung sai lắp then bằng (ISO 286 / DIN 6885)
   */
  getParallelKeyTolerances(b, h, isMetric, fitClass) {
    if (!isMetric) {
      return {
        keyWidthTol: '±0.002 in (Class 1)',
        shaftKeywayTol: fitClass === 'tight' ? '-0.000 / +0.001 in' : '-0.000 / +0.002 in',
        hubKeywayTol: '+0.002 / -0.000 in',
        depthTol: '+0.010 / -0.000 in'
      };
    }

    // IT9 for width b
    let it9_um = 30; // 30 um for 10-18mm
    if (b <= 3) it9_um = 25;
    else if (b <= 6) it9_um = 30;
    else if (b <= 10) it9_um = 36;
    else if (b <= 18) it9_um = 43;
    else if (b <= 30) it9_um = 52;
    else if (b <= 50) it9_um = 62;
    else it9_um = 74;

    const h9 = { es: 0, ei: -it9_um };
    let shaftTol = { sym: 'N9', es: 0, ei: -it9_um };
    if (fitClass === 'tight') {
      shaftTol = { sym: 'P9', es: -it9_um * 0.4, ei: -it9_um * 1.4 };
    } else if (fitClass === 'sliding') {
      shaftTol = { sym: 'JS9', es: it9_um / 2, ei: -it9_um / 2 };
    }

    const hubTol = { sym: 'JS9', ES: it9_um / 2, EI: -it9_um / 2 };
    const hubSlidingTol = { sym: 'D10', ES: it9_um * 2.0, EI: it9_um * 0.8 };

    return {
      keyWidthTol: `h9 (0 / -${(it9_um / 1000).toFixed(3)} mm)`,
      keyHeightTol: `h11 (0 / -${(it9_um * 2.5 / 1000).toFixed(3)} mm)`,
      shaftKeywayTol: `${shaftTol.sym} (${shaftTol.es >= 0 ? '+' : ''}${(shaftTol.es / 1000).toFixed(3)} / ${(shaftTol.ei / 1000).toFixed(3)} mm)`,
      hubKeywayTol: `JS9 (±${(it9_um / 2000).toFixed(3)} mm)`,
      hubSlidingTol: `D10 (+${(hubSlidingTol.ES / 1000).toFixed(3)} / +${(hubSlidingTol.EI / 1000).toFixed(3)} mm)`,
      depthTolShaft: '+0.1 / 0 mm (t1 <= 6) hoặc +0.2 / 0 mm',
      depthTolHub: '+0.1 / 0 mm (t2 <= 6) hoặc +0.2 / 0 mm'
    };
  },

  /**
   * Tính toán Then Bán Nguyệt (Woodruff Keys)
   * @param {Object} params - { units, woodruffTypeIndex, numKeys, shaftDiam, keySizeIndex }
   */
  calculateWoodruffKey(params) {
    const isMetric = params.units !== 'imperial';
    const typeIdx = Math.max(0, Math.min(9, params.woodruffTypeIndex || 0));
    const numKeys = params.numKeys === 2 ? 2 : 1;
    const d = parseFloat(params.shaftDiam) || (isMetric ? 25.0 : 1.0);

    const meta = KEYS_DATABASE.T_Key2_Name[typeIdx];
    const tabName = meta[1];
    const tabRatio = isMetric ? parseFloat(meta[2]) : parseFloat(meta[3]);
    const table = KEYS_DATABASE[tabName];

    // Filter compatible keys for this shaft diameter d
    const compatibleKeys = [];
    for (let i = 0; i < table.length; i++) {
      const row = table[i];
      const dMin = parseFloat(row[2]) * tabRatio;
      const dMax = parseFloat(row[3]) * tabRatio;
      if (d >= dMin * 0.95 && d <= dMax * 1.05) {
        compatibleKeys.push({ index: i, row });
      }
    }

    // Key selection: user keySizeIndex or default to first/best compatible
    let selectedEntry = compatibleKeys[0];
    if (params.keySizeIndex !== undefined && params.keySizeIndex >= 0 && params.keySizeIndex < table.length) {
      selectedEntry = { index: params.keySizeIndex, row: table[params.keySizeIndex] };
    } else if (compatibleKeys.length > 0) {
      selectedEntry = compatibleKeys[Math.floor(compatibleKeys.length / 2)];
    } else {
      selectedEntry = { index: 0, row: table[0] };
    }

    const row = selectedEntry.row;
    const keyName = row[0];
    const b = parseFloat(row[4]) * tabRatio;
    const h = parseFloat(row[5]) * tabRatio;
    const Dk = parseFloat(row[6]) * tabRatio;
    const e = parseFloat(row[7]) * tabRatio;
    const L = parseFloat(row[8]) * tabRatio;
    const t1 = parseFloat(row[9]) * tabRatio;
    const chamfer_s = parseFloat(row[10]) * tabRatio;

    // Remaining shaft diameter d1
    const d1 = numKeys === 1 ? (d - t1) : (d - 2 * t1);

    // Hub keyway depth t2
    const t2 = h + e - t1;
    const d2 = numKeys === 1 ? (d + t2) : (d + 2 * t2);

    // Key disc radius Rk
    const Rk = Dk / 2.0;

    // Contact areas calculation (DIN / ANSI)
    // Shaft contact depth: hs = t1 - chamfer_s
    const hs = Math.max(0, t1 - chamfer_s);
    // Hub contact depth: hh = h + e - t1 - chamfer_s
    const hh = Math.max(0, h + e - t1 - chamfer_s);
    const areaShaft = hs * L;
    const areaHub = hh * L;

    return {
      typeIdx,
      typeName: meta[0],
      tabName,
      rowIndex: selectedEntry.index,
      keyName,
      d,
      numKeys,
      b,
      h,
      Dk,
      Rk,
      e,
      L,
      t1,
      t2,
      d1,
      d2,
      chamfer_s,
      areaShaft,
      areaHub,
      compatibleKeys,
      allKeys: table.map((r, i) => ({ index: i, name: r[0], b: parseFloat(r[4]) * tabRatio, h: parseFloat(r[5]) * tabRatio })),
      isMetric
    };
  },

  /**
   * Tính toán Then Hoa Răng Chữ Nhật (Straight-Sided Splines)
   * @param {Object} params - { units, splineTypeIndex, splineSizeIndex, chosenLength }
   */
  calculateStraightSpline(params) {
    const isMetric = params.units !== 'imperial';
    const typeIdx = Math.max(0, Math.min(8, params.splineTypeIndex || 0));

    const meta = KEYS_DATABASE.T_spl1_Name[typeIdx];
    const tabName = meta[1];
    const tabRatio = isMetric ? parseFloat(meta[2]) : parseFloat(meta[3]);
    const table = KEYS_DATABASE[tabName];

    let splineSizeIdx = parseInt(params.splineSizeIndex, 10);
    if (isNaN(splineSizeIdx) || splineSizeIdx < 0 || splineSizeIdx >= table.length) {
      splineSizeIdx = Math.min(3, table.length - 1);
    }

    const row = table[splineSizeIdx];
    const splineName = row[0];
    const n = parseInt(row[1], 10);
    const d_minor = parseFloat(row[2]) * tabRatio;
    const D_major = parseFloat(row[3]) * tabRatio;
    const b_tooth = parseFloat(row[4]) * tabRatio;
    const chamfer_s = parseFloat(row[5]) * tabRatio;

    // Tooth height h
    const h = (D_major - d_minor) / 2.0;
    // Mean diameter dm
    const dm = (D_major + d_minor) / 2.0;

    // Pitch circumference & slot width on shaft
    const circularPitch = (Math.PI * dm) / n;
    const slotWidth = circularPitch - b_tooth;

    // Spline length L
    let chosenL = parseFloat(params.chosenLength);
    if (!chosenL || isNaN(chosenL)) {
      chosenL = Math.round(1.5 * D_major);
    }

    // Length list from DB
    const lenTabName = isMetric ? 'T_SplineLen_mm' : 'T_SplineLen_in';
    const lenTable = KEYS_DATABASE[lenTabName] || [];
    const availableLengths = lenTable.map(r => parseFloat(Array.isArray(r) ? r[0] : r));

    // Tolerances (ISO 14 / DIN 5464)
    const tolerances = this.getStraightSplineTolerances(d_minor, D_major, b_tooth, isMetric);

    return {
      typeIdx,
      typeName: meta[0],
      tabName,
      splineSizeIdx,
      splineName,
      n,
      d: d_minor,
      D: D_major,
      b: b_tooth,
      s: chamfer_s,
      h,
      dm,
      circularPitch,
      slotWidth,
      chosenL,
      availableLengths,
      allSplines: table.map((r, i) => ({
        index: i,
        name: r[0],
        n: r[1],
        d: parseFloat(r[2]) * tabRatio,
        D: parseFloat(r[3]) * tabRatio,
        b: parseFloat(r[4]) * tabRatio
      })),
      tolerances,
      isMetric
    };
  },

  /**
   * Dung sai then hoa răng chữ nhật (ISO 14 / DIN 5464)
   */
  getStraightSplineTolerances(d, D, b, isMetric) {
    if (!isMetric) {
      return {
        centeringType: 'Minor diameter centering',
        minorDiameterFit: 'Shaft: -0.001 / -0.002 in, Hub: +0.001 / 0 in',
        majorDiameterFit: 'Free clearance (Shaft h11, Hub H11)',
        widthFit: 'Shaft: -0.0005 / -0.0015 in, Hub: +0.001 / 0 in'
      };
    }

    return {
      centeringType: 'Định tâm theo đường kính trong d (Minor diameter centering)',
      minorDiameterFit: 'Lỗ H7 (0 / +0.021 mm) - Trục g6 (-0.007 / -0.020 mm) hoặc f7 (-0.020 / -0.041 mm)',
      majorDiameterFit: 'Khe hở tự do (Trục a11, Lỗ H11)',
      widthFit: 'Lỗ D10 (+0.040 / +0.098 mm) - Trục f7 (-0.013 / -0.028 mm) hoặc h9 (0 / -0.030 mm)'
    };
  },

  /**
   * Bảng so sánh 3 giải pháp mối ghép (Section 10.0)
   */
  getComparativeTable(shaftDiam, chosenLength, isMetric) {
    const d = parseFloat(shaftDiam) || (isMetric ? 40.0 : 1.5);
    const L = parseFloat(chosenLength) || (isMetric ? 56.0 : 2.25);

    // 1. Parallel key
    const pk = this.calculateParallelKey({ units: isMetric ? 'metric' : 'imperial', keyTypeIndex: 5, shaftDiam: d, chosenLength: L });
    // 2. Woodruff key
    const wk = this.calculateWoodruffKey({ units: isMetric ? 'metric' : 'imperial', woodruffTypeIndex: 2, shaftDiam: d });
    // 3. Straight spline
    const ss = this.calculateStraightSpline({ units: isMetric ? 'metric' : 'imperial', splineTypeIndex: 4, splineSizeIndex: 4, chosenLength: L });

    return {
      shaftDiam: d,
      chosenL: L,
      isMetric,
      parallelKey: {
        name: pk.keyName + ' (DIN 6885 Blatt 1)',
        dimensions: `b = ${pk.b.toFixed(2)}, h = ${pk.h.toFixed(2)}, t1 = ${pk.t1.toFixed(2)}`,
        d1: pk.d1.toFixed(2),
        area: ((pk.h - pk.t1) * pk.Lf_formA).toFixed(1)
      },
      woodruffKey: {
        name: wk.keyName + ' (DIN 6888 A)',
        dimensions: `b = ${wk.b.toFixed(2)}, h = ${wk.h.toFixed(2)}, Dk = ${wk.Dk.toFixed(2)}`,
        d1: wk.d1.toFixed(2),
        area: wk.areaHub.toFixed(1)
      },
      straightSpline: {
        name: ss.splineName + ' (ISO 14 Medium)',
        dimensions: `${ss.n} răng, D = ${ss.D.toFixed(2)}, d = ${ss.d.toFixed(2)}, b = ${ss.b.toFixed(2)}`,
        d1: ss.d.toFixed(2),
        area: (ss.n * ss.h * ss.chosenL).toFixed(1)
      }
    };
  }
};


/* --- SOURCE: keys-canvas.js --- */
/**
 * 2D CANVAS CAD RENDERING ENGINE: MODULE 8 KEYS & STRAIGHT-SIDED SPLINES
 * Hiển thị 3 HÌNH CẮT KỸ THUẬT:
 * 1. Hình Cắt Lỗ Moay-ơ (Hub Cross-Section)
 * 2. Hình Cắt Lắp Ghép (Assembly Cross-Section)
 * 3. Hình Cắt Trục (Shaft Cross-Section)
 * Hỗ trợ 1, 2, 3, 4 then và cử chỉ cảm ứng chuột & Multi-touch trên Mobile
 */

class KeysCanvas {
  constructor(canvasId) {
    this.canvas = document.getElementById(canvasId);
    if (!this.canvas) return;
    this.ctx = this.canvas.getContext('2d');

    this.displayView = 'triple'; // 'triple' (Bộ ba 3 hình), 'assembly', 'shaft', 'hub'
    this.jointType = 'parallel'; // 'parallel', 'woodruff', 'spline'

    this.scale = 1.0;
    this.panX = 0;
    this.panY = 0;
    this.isDragging = false;
    this.startX = 0;
    this.startY = 0;

    // Multi-touch
    this.initialPinchDistance = null;
    this.currentData = null;

    this.initEvents();
  }

  initEvents() {
    if (!this.canvas) return;

    // Mouse Pan & Zoom
    this.canvas.addEventListener('mousedown', (e) => {
      this.isDragging = true;
      this.startX = e.clientX - this.panX;
      this.startY = e.clientY - this.panY;
    });

    window.addEventListener('mousemove', (e) => {
      if (!this.isDragging) return;
      this.panX = e.clientX - this.startX;
      this.panY = e.clientY - this.startY;
      this.render();
    });

    window.addEventListener('mouseup', () => {
      this.isDragging = false;
    });

    this.canvas.addEventListener('wheel', (e) => {
      e.preventDefault();
      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      this.zoom(zoomFactor, e.offsetX, e.offsetY);
    }, { passive: false });

    // Touch events for mobile
    this.canvas.addEventListener('touchstart', (e) => {
      if (e.touches.length === 1) {
        this.isDragging = true;
        this.startX = e.touches[0].clientX - this.panX;
        this.startY = e.touches[0].clientY - this.panY;
      } else if (e.touches.length === 2) {
        this.isDragging = false;
        const dx = e.touches[0].clientX - e.touches[1].clientX;
        const dy = e.touches[0].clientY - e.touches[1].clientY;
        this.initialPinchDistance = Math.hypot(dx, dy);
      }
    }, { passive: true });

    this.canvas.addEventListener('touchmove', (e) => {
      if (e.touches.length === 1 && this.isDragging) {
        this.panX = e.touches[0].clientX - this.startX;
        this.panY = e.touches[0].clientY - this.startY;
        this.render();
      } else if (e.touches.length === 2 && this.initialPinchDistance) {
        const dx = e.touches[0].clientX - e.touches[1].clientX;
        const dy = e.touches[0].clientY - e.touches[1].clientY;
        const currentDistance = Math.hypot(dx, dy);
        const factor = currentDistance / this.initialPinchDistance;
        if (Math.abs(factor - 1) > 0.02) {
          const midX = (e.touches[0].clientX + e.touches[1].clientX) / 2;
          const midY = (e.touches[0].clientY + e.touches[1].clientY) / 2;
          const rect = this.canvas.getBoundingClientRect();
          this.zoom(factor > 1 ? 1.05 : 0.95, midX - rect.left, midY - rect.top);
          this.initialPinchDistance = currentDistance;
        }
      }
    }, { passive: true });

    this.canvas.addEventListener('touchend', () => {
      this.isDragging = false;
      this.initialPinchDistance = null;
    });
  }

  zoom(factor, centerX, centerY) {
    const newScale = Math.max(0.3, Math.min(8.0, this.scale * factor));
    const cx = centerX !== undefined ? centerX : this.canvas.width / 2;
    const cy = centerY !== undefined ? centerY : this.canvas.height / 2;
    this.panX = cx - (cx - this.panX) * (newScale / this.scale);
    this.panY = cy - (cy - this.panY) * (newScale / this.scale);
    this.scale = newScale;
    this.render();
  }

  resetView() {
    this.scale = 1.0;
    this.panX = 0;
    this.panY = 0;
    this.render();
  }

  setData(jointType, data) {
    this.jointType = jointType;
    this.currentData = data;
    this.render();
  }

  setDisplayView(view) {
    this.displayView = view;
    this.render();
  }

  render() {
    if (!this.canvas || !this.ctx) return;
    const ctx = this.ctx;
    const w = this.canvas.width;
    const h = this.canvas.height;

    ctx.clearRect(0, 0, w, h);
    this.drawGrid(ctx, w, h);

    if (!this.currentData) return;

    ctx.save();
    ctx.translate(w / 2 + this.panX, h / 2 + this.panY);
    ctx.scale(this.scale, this.scale);

    if (this.jointType === 'parallel') {
      this.renderParallelKeys(ctx);
    } else if (this.jointType === 'woodruff') {
      this.renderWoodruffKeys(ctx);
    } else if (this.jointType === 'spline') {
      this.renderStraightSplines(ctx);
    }

    ctx.restore();
  }

  drawGrid(ctx, w, h) {
    ctx.save();
    ctx.fillStyle = '#0b1120';
    ctx.fillRect(0, 0, w, h);

    ctx.strokeStyle = '#1e293b';
    ctx.lineWidth = 1;
    const step = 40;
    for (let x = 0; x < w; x += step) {
      ctx.beginPath();
      ctx.moveTo(x, 0);
      ctx.lineTo(x, h);
      ctx.stroke();
    }
    for (let y = 0; y < h; y += step) {
      ctx.beginPath();
      ctx.moveTo(0, y);
      ctx.lineTo(w, y);
      ctx.stroke();
    }
    ctx.restore();
  }

  drawAxes(ctx, cx, cy, radius) {
    ctx.save();
    ctx.strokeStyle = '#ef4444'; // Red centerline
    ctx.lineWidth = 1.2;
    ctx.setLineDash([10, 4, 2, 4]);

    const ext = radius * 1.35;
    ctx.beginPath();
    ctx.moveTo(cx - ext, cy);
    ctx.lineTo(cx + ext, cy);
    ctx.moveTo(cx, cy - ext);
    ctx.lineTo(cx, cy + ext);
    ctx.stroke();
    ctx.setLineDash([]);
    ctx.restore();
  }

  /**
   * Tính các góc đặt then theo số lượng then (1, 2, 3, 4)
   */
  getKeyAngles(numKeys) {
    if (numKeys === 4) {
      // 4 then cách đều 90° (12h, 3h, 6h, 9h)
      return [-Math.PI / 2, 0, Math.PI / 2, Math.PI];
    } else if (numKeys === 3) {
      // 3 then cách đều 120°
      return [-Math.PI / 2, -Math.PI / 2 + (2 * Math.PI) / 3, -Math.PI / 2 + (4 * Math.PI) / 3];
    } else if (numKeys === 2) {
      // 2 then đối xứng 180° (12h và 6h)
      return [-Math.PI / 2, Math.PI / 2];
    }
    // 1 then ở đỉnh (12h)
    return [-Math.PI / 2];
  }

  // =========================================================================
  // BỘ 3 HÌNH CẮT THEN BẰNG (PARALLEL KEYS: HUB, ASSEMBLY, SHAFT)
  // =========================================================================
  renderParallelKeys(ctx) {
    const data = this.currentData;
    const d = data.d;
    const b = data.b;
    const h = data.h;
    const t1 = data.t1;
    const t2 = data.t2;
    const numKeys = data.numKeys || 1;
    const angles = this.getKeyAngles(numKeys);

    if (this.displayView === 'triple') {
      // BỘ BA 3 HÌNH NẰM CẠNH NHAU
      const spacing = 380;
      const pxPerUnit = 135 / d; // Căn chỉnh tỷ lệ vừa vặn 3 hình
      const r_shaft = (d / 2) * pxPerUnit;
      const r_hub = r_shaft * 1.8;
      const w_key = b * pxPerUnit;
      const h_key = h * pxPerUnit;
      const depth1 = t1 * pxPerUnit;
      const depth2 = t2 * pxPerUnit;

      // 1. Bên trái: Hình cắt lỗ Moay-ơ (Hub)
      this.drawSingleHubView(ctx, -spacing, 0, r_shaft, r_hub, w_key, depth2, angles, data);

      // 2. Ở giữa: Hình cắt Lắp ghép (Assembly)
      this.drawSingleAssemblyView(ctx, 0, 0, r_shaft, r_hub, w_key, h_key, depth1, depth2, angles, data);

      // 3. Bên phải: Hình cắt Trục (Shaft)
      this.drawSingleShaftView(ctx, spacing, 0, r_shaft, w_key, depth1, angles, data);

    } else {
      // PHÓNG TO 1 HÌNH RIÊNG LẺ
      const pxPerUnit = 220 / d;
      const r_shaft = (d / 2) * pxPerUnit;
      const r_hub = r_shaft * 1.8;
      const w_key = b * pxPerUnit;
      const h_key = h * pxPerUnit;
      const depth1 = t1 * pxPerUnit;
      const depth2 = t2 * pxPerUnit;

      if (this.displayView === 'hub') {
        this.drawSingleHubView(ctx, 0, 0, r_shaft, r_hub, w_key, depth2, angles, data);
      } else if (this.displayView === 'shaft') {
        this.drawSingleShaftView(ctx, 0, 0, r_shaft, w_key, depth1, angles, data);
      } else {
        this.drawSingleAssemblyView(ctx, 0, 0, r_shaft, r_hub, w_key, h_key, depth1, depth2, angles, data);
      }
    }
  }

  // 1. VẼ MẶT CẮT LỖ MOAY-Ơ (HUB CROSS-SECTION)
  drawSingleHubView(ctx, cx, cy, r_shaft, r_hub, w_key, depth2, angles, data) {
    ctx.save();
    this.drawAxes(ctx, cx, cy, r_hub);

    // Hub ring body
    ctx.fillStyle = 'rgba(30, 41, 59, 0.9)';
    ctx.strokeStyle = '#64748b';
    ctx.lineWidth = 2;

    ctx.beginPath();
    ctx.arc(cx, cy, r_hub, 0, Math.PI * 2);
    ctx.arc(cx, cy, r_shaft, 0, Math.PI * 2, true);
    ctx.fill();
    ctx.stroke();

    // Metallic Hatching for Hub
    this.drawHatchingRing(ctx, cx, cy, r_shaft, r_hub, '#334155');

    // Hub keyways (khoét rãnh ra ngoài)
    angles.forEach(ang => {
      ctx.save();
      ctx.translate(cx, cy);
      ctx.rotate(ang + Math.PI / 2);
      ctx.fillStyle = '#0b1120';
      ctx.fillRect(-w_key / 2, -r_shaft - depth2, w_key, depth2);
      ctx.strokeStyle = '#f59e0b';
      ctx.lineWidth = 2;
      ctx.strokeRect(-w_key / 2, -r_shaft - depth2, w_key, depth2);
      ctx.restore();
    });

    // Outer and Inner Hub contours
    ctx.strokeStyle = '#94a3b8';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(cx, cy, r_hub, 0, Math.PI * 2);
    ctx.stroke();
    ctx.strokeStyle = '#38bdf8';
    ctx.beginPath();
    ctx.arc(cx, cy, r_shaft, 0, Math.PI * 2);
    ctx.stroke();

    // Kích thước kỹ thuật cho Lỗ
    this.drawHubDimensions(ctx, cx, cy, r_shaft, r_hub, w_key, depth2, data);

    // Tiêu đề hình
    ctx.fillStyle = '#38bdf8';
    ctx.font = 'bold 13px -apple-system, BlinkMacSystemFont, sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('1. HÌNH CẮT LỖ MOAY-Ơ (HUB)', cx, cy + r_hub + 45);

    ctx.restore();
  }

  // 2. VẼ MẶT CẮT LẮP GHÉP (ASSEMBLY CROSS-SECTION)
  drawSingleAssemblyView(ctx, cx, cy, r_shaft, r_hub, w_key, h_key, depth1, depth2, angles, data) {
    ctx.save();
    this.drawAxes(ctx, cx, cy, r_hub);

    // 1. Hub outer ring
    ctx.fillStyle = 'rgba(30, 41, 59, 0.85)';
    ctx.strokeStyle = '#64748b';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(cx, cy, r_hub, 0, Math.PI * 2);
    ctx.arc(cx, cy, r_shaft, 0, Math.PI * 2, true);
    ctx.fill();
    ctx.stroke();
    this.drawHatchingRing(ctx, cx, cy, r_shaft, r_hub, '#334155');

    // 2. Shaft body inside
    ctx.fillStyle = 'rgba(6, 182, 212, 0.15)';
    ctx.strokeStyle = '#06b6d4';
    ctx.lineWidth = 2.5;
    ctx.beginPath();
    ctx.arc(cx, cy, r_shaft, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();

    // 3. Keys and Keyways
    angles.forEach(ang => {
      ctx.save();
      ctx.translate(cx, cy);
      ctx.rotate(ang + Math.PI / 2);

      // Hub notch
      ctx.strokeStyle = '#64748b';
      ctx.strokeRect(-w_key / 2, -r_shaft - depth2, w_key, depth2);

      // Shaft notch
      ctx.fillStyle = '#0b1120';
      ctx.fillRect(-w_key / 2, -r_shaft, w_key, depth1);
      ctx.strokeStyle = '#06b6d4';
      ctx.strokeRect(-w_key / 2, -r_shaft, w_key, depth1);

      // Key body (Solid amber with cross hatch)
      const keyTopY = -r_shaft + depth1 - h_key;
      ctx.fillStyle = 'rgba(245, 158, 11, 0.9)';
      ctx.strokeStyle = '#fbbf24';
      ctx.lineWidth = 2;
      ctx.fillRect(-w_key / 2, keyTopY, w_key, h_key);
      ctx.strokeRect(-w_key / 2, keyTopY, w_key, h_key);

      // Key hatch
      ctx.strokeStyle = 'rgba(255, 255, 255, 0.35)';
      ctx.lineWidth = 1;
      ctx.beginPath();
      for (let x = -w_key / 2; x <= w_key / 2 + h_key; x += 6) {
        ctx.moveTo(x, keyTopY);
        ctx.lineTo(x - h_key, keyTopY + h_key);
      }
      ctx.stroke();

      ctx.restore();
    });

    // Assembly Dimensions
    this.drawAssemblyDimensions(ctx, cx, cy, r_shaft, w_key, h_key, depth1, depth2, data);

    // Tiêu đề hình
    ctx.fillStyle = '#f59e0b';
    ctx.font = 'bold 13px -apple-system, BlinkMacSystemFont, sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('2. HÌNH CẮT LẮP GHÉP (ASSEMBLY)', cx, cy + r_hub + 45);

    ctx.restore();
  }

  // 3. VẼ MẶT CẮT TRỤC (SHAFT CROSS-SECTION)
  drawSingleShaftView(ctx, cx, cy, r_shaft, w_key, depth1, angles, data) {
    ctx.save();
    this.drawAxes(ctx, cx, cy, r_shaft);

    // Solid Shaft circle
    ctx.fillStyle = 'rgba(6, 182, 212, 0.2)';
    ctx.strokeStyle = '#06b6d4';
    ctx.lineWidth = 2.5;

    ctx.beginPath();
    ctx.arc(cx, cy, r_shaft, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();

    // Metallic Hatching for Shaft
    this.drawHatchingCircle(ctx, cx, cy, r_shaft, '#0e7490');

    // Shaft keyways (khoét rãnh vào trong)
    angles.forEach(ang => {
      ctx.save();
      ctx.translate(cx, cy);
      ctx.rotate(ang + Math.PI / 2);
      ctx.fillStyle = '#0b1120';
      ctx.fillRect(-w_key / 2, -r_shaft, w_key, depth1);
      ctx.strokeStyle = '#06b6d4';
      ctx.lineWidth = 2;
      ctx.strokeRect(-w_key / 2, -r_shaft, w_key, depth1);
      ctx.restore();
    });

    // Shaft Dimensions
    this.drawShaftDimensions(ctx, cx, cy, r_shaft, w_key, depth1, data);

    // Tiêu đề hình
    ctx.fillStyle = '#10b981';
    ctx.font = 'bold 13px -apple-system, BlinkMacSystemFont, sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('3. HÌNH CẮT TRỤC (SHAFT)', cx, cy + r_shaft * 1.8 + 45);

    ctx.restore();
  }

  // Đường gióng kích thước Lỗ Moay-ơ
  drawHubDimensions(ctx, cx, cy, r_shaft, r_hub, w_key, depth2, data) {
    ctx.save();
    ctx.strokeStyle = '#94a3b8';
    ctx.fillStyle = '#f8fafc';
    ctx.font = '11px "JetBrains Mono", Consolas, monospace';
    ctx.lineWidth = 1;

    // Kích thước b trên đỉnh
    const dimY = cy - r_shaft - depth2 - 20;
    ctx.beginPath();
    ctx.moveTo(cx - w_key / 2, cy - r_shaft - depth2);
    ctx.lineTo(cx - w_key / 2, dimY);
    ctx.moveTo(cx + w_key / 2, cy - r_shaft - depth2);
    ctx.lineTo(cx + w_key / 2, dimY);
    ctx.moveTo(cx - w_key / 2, dimY + 4);
    ctx.lineTo(cx + w_key / 2, dimY + 4);
    ctx.stroke();
    ctx.textAlign = 'center';
    ctx.fillText(`b = ${data.b.toFixed(2)}`, cx, dimY - 2);

    // Kích thước t2 bên phải
    ctx.textAlign = 'left';
    ctx.fillText(`t2 = ${data.t2.toFixed(2)}`, cx + w_key / 2 + 8, cy - r_shaft - depth2 / 2 + 4);

    // Đường kính lỗ Ø d
    ctx.textAlign = 'center';
    ctx.fillText(`Ø Lỗ = ${data.d.toFixed(1)}${data.isMetric ? ' mm' : ' in'}`, cx, cy + 18);

    ctx.restore();
  }

  // Đường gióng kích thước Lắp Ghép
  drawAssemblyDimensions(ctx, cx, cy, r_shaft, w_key, h_key, depth1, depth2, data) {
    ctx.save();
    ctx.strokeStyle = '#f59e0b';
    ctx.fillStyle = '#f8fafc';
    ctx.font = '11px "JetBrains Mono", Consolas, monospace';
    ctx.lineWidth = 1;

    // Then b x h
    const dimY = cy - r_shaft + depth1 - h_key - 22;
    ctx.textAlign = 'center';
    ctx.fillText(`Then: ${data.b.toFixed(1)} x ${data.h.toFixed(1)}`, cx, dimY);

    // Đường kính tiếp xúc d
    ctx.fillText(`Ø d = ${data.d.toFixed(1)}`, cx, cy + 18);

    // Thông số t1 và t2
    ctx.textAlign = 'left';
    ctx.fillStyle = '#06b6d4';
    ctx.fillText(`t1 = ${data.t1.toFixed(2)}`, cx + w_key / 2 + 8, cy - r_shaft + depth1 / 2 + 4);
    ctx.fillStyle = '#f59e0b';
    ctx.fillText(`t2 = ${data.t2.toFixed(2)}`, cx + w_key / 2 + 8, cy - r_shaft - depth2 / 2 + 4);

    ctx.restore();
  }

  // Đường gióng kích thước Trục
  drawShaftDimensions(ctx, cx, cy, r_shaft, w_key, depth1, data) {
    ctx.save();
    ctx.strokeStyle = '#94a3b8';
    ctx.fillStyle = '#f8fafc';
    ctx.font = '11px "JetBrains Mono", Consolas, monospace';
    ctx.lineWidth = 1;

    // Kích thước b trên đỉnh
    const dimY = cy - r_shaft - 20;
    ctx.beginPath();
    ctx.moveTo(cx - w_key / 2, cy - r_shaft);
    ctx.lineTo(cx - w_key / 2, dimY);
    ctx.moveTo(cx + w_key / 2, cy - r_shaft);
    ctx.lineTo(cx + w_key / 2, dimY);
    ctx.moveTo(cx - w_key / 2, dimY + 4);
    ctx.lineTo(cx + w_key / 2, dimY + 4);
    ctx.stroke();
    ctx.textAlign = 'center';
    ctx.fillText(`b = ${data.b.toFixed(2)}`, cx, dimY - 2);

    // Kích thước t1 bên phải
    ctx.textAlign = 'left';
    ctx.fillText(`t1 = ${data.t1.toFixed(2)}`, cx + w_key / 2 + 8, cy - r_shaft + depth1 / 2 + 4);

    // Đường kính trục và đáy rãnh d1
    ctx.textAlign = 'center';
    ctx.fillText(`Ø d = ${data.d.toFixed(1)}${data.isMetric ? ' mm' : ' in'}`, cx, cy + 16);
    ctx.fillStyle = '#10b981';
    ctx.fillText(`d1 = ${data.d1.toFixed(2)}`, cx, cy + 34);

    ctx.restore();
  }

  // Hatching utilities
  drawHatchingRing(ctx, cx, cy, rInner, rOuter, color) {
    ctx.save();
    ctx.strokeStyle = color;
    ctx.lineWidth = 0.8;
    ctx.beginPath();
    ctx.rect(cx - rOuter, cy - rOuter, rOuter * 2, rOuter * 2);
    ctx.clip();

    ctx.beginPath();
    for (let x = cx - rOuter * 2; x <= cx + rOuter * 2; x += 12) {
      ctx.moveTo(x, cy - rOuter);
      ctx.lineTo(x + rOuter * 2, cy + rOuter);
    }
    ctx.stroke();
    ctx.restore();
  }

  drawHatchingCircle(ctx, cx, cy, radius, color) {
    ctx.save();
    ctx.strokeStyle = color;
    ctx.lineWidth = 0.8;
    ctx.beginPath();
    ctx.arc(cx, cy, radius, 0, Math.PI * 2);
    ctx.clip();

    ctx.beginPath();
    for (let x = cx - radius * 2; x <= cx + radius * 2; x += 12) {
      ctx.moveTo(x, cy - radius);
      ctx.lineTo(x + radius * 2, cy + radius);
    }
    ctx.stroke();
    ctx.restore();
  }

  // =========================================================================
  // BỘ HÌNH THEN BÁN NGUYỆT (WOODRUFF) & THEN HOA (SPLINES)
  // =========================================================================
  renderWoodruffKeys(ctx) {
    const data = this.currentData;
    const d = data.d;
    const b = data.b;
    const h = data.h;
    const t1 = data.t1;
    const t2 = data.t2;
    const numKeys = data.numKeys || 1;
    const angles = this.getKeyAngles(numKeys);

    const spacing = 380;
    const pxPerUnit = 135 / d;
    const r_shaft = (d / 2) * pxPerUnit;
    const r_hub = r_shaft * 1.8;
    const w_key = b * pxPerUnit;
    const h_key = h * pxPerUnit;
    const depth1 = t1 * pxPerUnit;
    const depth2 = t2 * pxPerUnit;

    this.drawSingleHubView(ctx, -spacing, 0, r_shaft, r_hub, w_key, depth2, angles, data);
    this.drawSingleAssemblyView(ctx, 0, 0, r_shaft, r_hub, w_key, h_key, depth1, depth2, angles, data);
    this.drawSingleShaftView(ctx, spacing, 0, r_shaft, w_key, depth1, angles, data);
  }

  renderStraightSplines(ctx) {
    const data = this.currentData;
    const n = data.n;
    const d = data.d; // minor
    const D = data.D; // major
    const b = data.b;

    const spacing = 380;
    const pxPerUnit = 120 / D;
    const r_minor = (d / 2) * pxPerUnit;
    const r_major = (D / 2) * pxPerUnit;
    const r_hub = r_major * 1.6;
    const halfB = (b / 2) * pxPerUnit;

    // 1. Hub spline
    this.drawSplineHub(ctx, -spacing, 0, r_minor, r_major, r_hub, n, halfB, data);
    // 2. Assembly spline
    this.drawSplineAssembly(ctx, 0, 0, r_minor, r_major, r_hub, n, halfB, data);
    // 3. Shaft spline
    this.drawSplineShaft(ctx, spacing, 0, r_minor, r_major, n, halfB, data);
  }

  drawSplineHub(ctx, cx, cy, rMinor, rMajor, rHub, n, halfB, data) {
    ctx.save();
    this.drawAxes(ctx, cx, cy, rHub);
    ctx.fillStyle = 'rgba(30, 41, 59, 0.9)';
    ctx.strokeStyle = '#64748b';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(cx, cy, rHub, 0, Math.PI * 2);
    ctx.arc(cx, cy, rMajor, 0, Math.PI * 2, true);
    ctx.fill();
    ctx.stroke();

    ctx.fillStyle = '#38bdf8';
    ctx.font = 'bold 13px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('1. HÌNH CẮT LỖ THEN HOA (HUB)', cx, cy + rHub + 45);
    ctx.restore();
  }

  drawSplineAssembly(ctx, cx, cy, rMinor, rMajor, rHub, n, halfB, data) {
    ctx.save();
    this.drawAxes(ctx, cx, cy, rHub);
    this.drawSplineToothLoop(ctx, cx, cy, rMinor, rMajor, n, halfB, 'rgba(6, 182, 212, 0.25)', '#06b6d4');

    ctx.fillStyle = '#f59e0b';
    ctx.font = 'bold 13px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('2. HÌNH CẮT LẮP GHÉP (ASSEMBLY)', cx, cy + rHub + 45);
    ctx.restore();
  }

  drawSplineShaft(ctx, cx, cy, rMinor, rMajor, n, halfB, data) {
    ctx.save();
    this.drawAxes(ctx, cx, cy, rMajor * 1.3);
    this.drawSplineToothLoop(ctx, cx, cy, rMinor, rMajor, n, halfB, 'rgba(16, 185, 129, 0.25)', '#10b981');

    ctx.fillStyle = '#10b981';
    ctx.font = 'bold 13px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('3. HÌNH CẮT TRỤC THEN HOA (SHAFT)', cx, cy + rMajor * 1.6 + 45);
    ctx.restore();
  }

  drawSplineToothLoop(ctx, cx, cy, rMinor, rMajor, n, halfB, fillColor, strokeColor) {
    ctx.save();
    ctx.fillStyle = fillColor;
    ctx.strokeStyle = strokeColor;
    ctx.lineWidth = 2;
    ctx.beginPath();
    const angleStep = (Math.PI * 2) / n;

    for (let i = 0; i < n; i++) {
      const theta = i * angleStep;
      const cosT = Math.cos(theta);
      const sinT = Math.sin(theta);
      const tanX = -sinT;
      const tanY = cosT;

      const p1x = cx + rMajor * cosT - halfB * tanX;
      const p1y = cy + rMajor * sinT - halfB * tanY;
      const p2x = cx + rMajor * cosT + halfB * tanX;
      const p2y = cy + rMajor * sinT + halfB * tanY;

      const p0x = cx + rMinor * cosT - halfB * tanX;
      const p0y = cy + rMinor * sinT - halfB * tanY;
      const p3x = cx + rMinor * cosT + halfB * tanX;
      const p3y = cy + rMinor * sinT + halfB * tanY;

      if (i === 0) ctx.moveTo(p0x, p0y);
      else ctx.lineTo(p0x, p0y);
      ctx.lineTo(p1x, p1y);
      ctx.lineTo(p2x, p2y);
      ctx.lineTo(p3x, p3y);

      const nextTheta = (i + 1) * angleStep;
      const nextCos = Math.cos(nextTheta);
      const nextSin = Math.sin(nextTheta);
      const nextTanX = -nextSin;
      const nextTanY = nextCos;
      const nextP0x = cx + rMinor * nextCos - halfB * nextTanX;
      const nextP0y = cy + rMinor * nextSin - halfB * nextTanY;

      const startAng = Math.atan2(p3y - cy, p3x - cx);
      const endAng = Math.atan2(nextP0y - cy, nextP0x - cx);
      ctx.arc(cx, cy, rMinor, startAng, endAng);
    }
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
    ctx.restore();
  }

  downloadImage() {
    if (!this.canvas) return;
    const link = document.createElement('a');
    link.download = `Keys_3Views_${this.jointType}_CAD.png`;
    link.href = this.canvas.toDataURL('image/png');
    link.click();
  }
}


/* --- SOURCE: keys-dxf.js --- */
/**
 * CAD DXF EXPORT ENGINE: MODULE 8 KEYS & STRAIGHT-SIDED SPLINES
 * Standard: DXF Release 12 (AC1009 ASCII format)
 * Compatible: AutoCAD, SolidWorks, Autodesk Inventor, LibreCAD, BricsCAD, ZWCAD
 * 100% Offline, Zero-CORS, Blob download
 */

const KeysDXF = {
  /**
   * Xuất bản vẽ 2D DXF cho Then Bằng, Then Bán Nguyệt, hoặc Then Hoa
   * @param {string} jointType - 'parallel', 'woodruff', 'spline'
   * @param {Object} data - Dữ liệu tính toán từ KeysCalc
   * @param {string} sectionType - 'cross', 'long'
   */
  exportDXF(jointType, data, sectionType = 'cross') {
    let d = '';
    // Header
    d += '0\nSECTION\n2\nHEADER\n9\n$ACADVER\n1\nAC1009\n0\nENDSEC\n';

    // Tables
    d += '0\nSECTION\n2\nTABLES\n';
    d += '0\nTABLE\n2\nLTYPE\n70\n1\n';
    d += '0\nLTYPE\n2\nCENTER\n70\n0\n3\nCenterline\n72\n65\n73\n2\n40\n10.0\n49\n7.5\n49\n-2.5\n';
    d += '0\nENDTAB\n';

    d += '0\nTABLE\n2\nLAYER\n70\n5\n';
    d += '0\nLAYER\n2\nCONTOUR_SHAFT\n70\n0\n62\n4\n6\nCONTINUOUS\n'; // Cyan
    d += '0\nLAYER\n2\nCONTOUR_HUB\n70\n0\n62\n1\n6\nCONTINUOUS\n';   // Red
    d += '0\nLAYER\n2\nCONTOUR_KEY\n70\n0\n62\n2\n6\nCONTINUOUS\n';   // Yellow
    d += '0\nLAYER\n2\nCENTER\n70\n0\n62\n7\n6\nCENTER\n';           // White
    d += '0\nLAYER\n2\nMFG_TABLE\n70\n0\n62\n7\n6\nCONTINUOUS\n';     // White
    d += '0\nENDTAB\n0\nENDSEC\n';

    // Entities
    d += '0\nSECTION\n2\nENTITIES\n';

    // Center axes
    const rShaft = (jointType === 'spline' ? data.D / 2 : data.d / 2) * 1.5;
    d += this.dxfLine(-rShaft * 1.3, 0, rShaft * 1.3, 0, 'CENTER');
    d += this.dxfLine(0, -rShaft * 1.3, 0, rShaft * 1.3, 'CENTER');

    if (jointType === 'parallel') {
      d += this.generateParallelKeyDXF(data, sectionType);
    } else if (jointType === 'woodruff') {
      d += this.generateWoodruffKeyDXF(data, sectionType);
    } else if (jointType === 'spline') {
      d += this.generateStraightSplineDXF(data, sectionType);
    }

    // Manufacturing Parameters Table (Bảng chế tạo)
    d += this.generateManufacturingTable(jointType, data);

    d += '0\nENDSEC\n0\nEOF\n';

    // Blob download
    const blob = new Blob([d], { type: 'application/dxf' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `MITCalc_${jointType}_key_drawing.dxf`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  },

  dxfLine(x1, y1, x2, y2, layer) {
    return `0\nLINE\n8\n${layer}\n10\n${x1.toFixed(4)}\n20\n${y1.toFixed(4)}\n30\n0.0\n11\n${x2.toFixed(4)}\n21\n${y2.toFixed(4)}\n31\n0.0\n`;
  },

  dxfCircle(cx, cy, r, layer) {
    return `0\nCIRCLE\n8\n${layer}\n10\n${cx.toFixed(4)}\n20\n${cy.toFixed(4)}\n30\n0.0\n40\n${r.toFixed(4)}\n`;
  },

  dxfText(x, y, height, text, layer) {
    return `0\nTEXT\n8\n${layer}\n10\n${x.toFixed(4)}\n20\n${y.toFixed(4)}\n30\n0.0\n40\n${height.toFixed(4)}\n1\n${text}\n`;
  },

  generateParallelKeyDXF(data, sectionType) {
    let d = '';
    const r = data.d / 2;
    const b = data.b;
    const h = data.h;
    const t1 = data.t1;
    const t2 = data.t2;

    if (sectionType === 'cross') {
      // Shaft circle
      d += this.dxfCircle(0, 0, r, 'CONTOUR_SHAFT');
      // Shaft keyway slot
      d += this.dxfLine(-b / 2, r, -b / 2, r - t1, 'CONTOUR_SHAFT');
      d += this.dxfLine(-b / 2, r - t1, b / 2, r - t1, 'CONTOUR_SHAFT');
      d += this.dxfLine(b / 2, r - t1, b / 2, r, 'CONTOUR_SHAFT');

      // Key cross section
      d += this.dxfLine(-b / 2, r - t1, -b / 2, r - t1 + h, 'CONTOUR_KEY');
      d += this.dxfLine(-b / 2, r - t1 + h, b / 2, r - t1 + h, 'CONTOUR_KEY');
      d += this.dxfLine(b / 2, r - t1 + h, b / 2, r - t1, 'CONTOUR_KEY');
      d += this.dxfLine(b / 2, r - t1, -b / 2, r - t1, 'CONTOUR_KEY');

      // Hub outer circle & keyway
      const rHub = r * 1.8;
      d += this.dxfCircle(0, 0, rHub, 'CONTOUR_HUB');
      d += this.dxfLine(-b / 2, r, -b / 2, r + t2, 'CONTOUR_HUB');
      d += this.dxfLine(-b / 2, r + t2, b / 2, r + t2, 'CONTOUR_HUB');
      d += this.dxfLine(b / 2, r + t2, b / 2, r, 'CONTOUR_HUB');
    } else {
      // Longitudinal view
      const L = data.chosenL;
      const Lshaft = L * 1.5;
      d += this.dxfLine(-Lshaft / 2, -r, Lshaft / 2, -r, 'CONTOUR_SHAFT');
      d += this.dxfLine(-Lshaft / 2, r, Lshaft / 2, r, 'CONTOUR_SHAFT');
      d += this.dxfLine(-Lshaft / 2, -r, -Lshaft / 2, r, 'CONTOUR_SHAFT');
      d += this.dxfLine(Lshaft / 2, -r, Lshaft / 2, r, 'CONTOUR_SHAFT');

      // Key body
      d += this.dxfLine(-L / 2, r - t1, L / 2, r - t1, 'CONTOUR_KEY');
      d += this.dxfLine(-L / 2, r - t1 + h, L / 2, r - t1 + h, 'CONTOUR_KEY');
      d += this.dxfLine(-L / 2, r - t1, -L / 2, r - t1 + h, 'CONTOUR_KEY');
      d += this.dxfLine(L / 2, r - t1, L / 2, r - t1 + h, 'CONTOUR_KEY');
    }
    return d;
  },

  generateWoodruffKeyDXF(data, sectionType) {
    let d = '';
    const r = data.d / 2;
    const b = data.b;
    const h = data.h;
    const Dk = data.Dk;
    const Rk = Dk / 2;
    const t1 = data.t1;
    const t2 = data.t2;

    if (sectionType === 'cross') {
      d += this.dxfCircle(0, 0, r, 'CONTOUR_SHAFT');
      d += this.dxfCircle(0, 0, r * 1.8, 'CONTOUR_HUB');
      d += this.dxfLine(-b / 2, r - t1, -b / 2, r + t2, 'CONTOUR_KEY');
      d += this.dxfLine(-b / 2, r + t2, b / 2, r + t2, 'CONTOUR_KEY');
      d += this.dxfLine(b / 2, r + t2, b / 2, r - t1, 'CONTOUR_KEY');
      d += this.dxfLine(b / 2, r - t1, -b / 2, r - t1, 'CONTOUR_KEY');
    } else {
      const Lshaft = Dk * 2.0;
      d += this.dxfLine(-Lshaft / 2, -r, Lshaft / 2, -r, 'CONTOUR_SHAFT');
      d += this.dxfLine(-Lshaft / 2, r, Lshaft / 2, r, 'CONTOUR_SHAFT');

      // Key disc
      const discY = r - t1 + Rk;
      d += this.dxfCircle(0, discY, Rk, 'CONTOUR_KEY');
    }
    return d;
  },

  generateStraightSplineDXF(data, sectionType) {
    let d = '';
    const n = data.n;
    const rMinor = data.d / 2;
    const rMajor = data.D / 2;
    const b = data.b;
    const halfB = b / 2;

    if (sectionType === 'cross') {
      d += this.dxfCircle(0, 0, rMinor, 'CONTOUR_SHAFT');
      d += this.dxfCircle(0, 0, rMajor, 'CONTOUR_SHAFT');
      d += this.dxfCircle(0, 0, rMajor * 1.5, 'CONTOUR_HUB');

      const angleStep = (Math.PI * 2) / n;
      for (let i = 0; i < n; i++) {
        const theta = i * angleStep;
        const cosT = Math.cos(theta);
        const sinT = Math.sin(theta);
        const tanX = -sinT;
        const tanY = cosT;

        const p1x = rMajor * cosT - halfB * tanX;
        const p1y = rMajor * sinT - halfB * tanY;
        const p2x = rMajor * cosT + halfB * tanX;
        const p2y = rMajor * sinT + halfB * tanY;

        const p0x = rMinor * cosT - halfB * tanX;
        const p0y = rMinor * sinT - halfB * tanY;
        const p3x = rMinor * cosT + halfB * tanX;
        const p3y = rMinor * sinT + halfB * tanY;

        d += this.dxfLine(p0x, p0y, p1x, p1y, 'CONTOUR_SHAFT');
        d += this.dxfLine(p1x, p1y, p2x, p2y, 'CONTOUR_SHAFT');
        d += this.dxfLine(p2x, p2y, p3x, p3y, 'CONTOUR_SHAFT');
      }
    } else {
      const L = data.chosenL;
      const Lshaft = L * 1.5;
      d += this.dxfLine(-Lshaft / 2, -rMinor, Lshaft / 2, -rMinor, 'CONTOUR_SHAFT');
      d += this.dxfLine(-Lshaft / 2, rMinor, Lshaft / 2, rMinor, 'CONTOUR_SHAFT');
      d += this.dxfLine(-L / 2, rMajor, L / 2, rMajor, 'CONTOUR_KEY');
      d += this.dxfLine(-L / 2, -rMajor, L / 2, -rMajor, 'CONTOUR_KEY');
    }
    return d;
  },

  generateManufacturingTable(jointType, data) {
    let d = '';
    const startX = (jointType === 'spline' ? data.D : data.d) * 1.2;
    let startY = 40;
    const lineH = 4.5;
    const txtSize = 2.5;

    const rows = [
      '--- THONG SO CHE TAO MOI GHEP ---',
      `Tieu chuan: ${data.typeName}`,
      `Quy cach: ${data.keyName || data.splineName}`
    ];

    if (jointType === 'parallel') {
      rows.push(`Duong kinh truc: d = ${data.d.toFixed(2)}${data.isMetric ? ' mm' : ' in'}`);
      rows.push(`Chieu rong then: b = ${data.b.toFixed(2)} (${data.tolerances.keyWidthTol})`);
      rows.push(`Chieu cao then: h = ${data.h.toFixed(2)} (${data.tolerances.keyHeightTol})`);
      rows.push(`Chieu sau ranh truc: t1 = ${data.t1.toFixed(2)} (${data.tolerances.depthTolShaft})`);
      rows.push(`Chieu sau ranh moay-o: t2 = ${data.t2.toFixed(2)} (${data.tolerances.depthTolHub})`);
      rows.push(`Chieu dai then: L = ${data.chosenL.toFixed(2)}`);
      rows.push(`Chieu dai lam viec: Lf = ${data.Lf_formA.toFixed(2)}`);
    } else if (jointType === 'woodruff') {
      rows.push(`Duong kinh truc: d = ${data.d.toFixed(2)}`);
      rows.push(`Chieu rong then: b = ${data.b.toFixed(2)}`);
      rows.push(`Chieu cao then: h = ${data.h.toFixed(2)}`);
      rows.push(`Duong kinh dia: Dk = ${data.Dk.toFixed(2)}`);
      rows.push(`Chieu sau ranh truc: t = ${data.t1.toFixed(2)}`);
      rows.push(`Chieu dai danh nghia: L = ${data.L.toFixed(2)}`);
    } else if (jointType === 'spline') {
      rows.push(`So then (rang): n = ${data.n}`);
      rows.push(`Duong kinh ngoai: D = ${data.D.toFixed(2)}`);
      rows.push(`Duong kinh trong: d = ${data.d.toFixed(2)}`);
      rows.push(`Chieu rong then: b = ${data.b.toFixed(2)}`);
      rows.push(`Vat mep: s = ${data.s.toFixed(2)}`);
      rows.push(`Chieu dai then hoa: L = ${data.chosenL.toFixed(2)}`);
    }

    for (let i = 0; i < rows.length; i++) {
      d += this.dxfText(startX, startY - i * lineH, txtSize, rows[i], 'MFG_TABLE');
    }

    return d;
  }
};


/* --- SOURCE: keys-ui.js --- */
/**
 * UI CONTROLLER: MODULE 8 KEYS & STRAIGHT-SIDED SPLINES
 * Connects DOM inputs, KeysCalc engine & 3-View Canvas CAD
 */

document.addEventListener('DOMContentLoaded', () => {
  const canvas = new KeysCanvas('keysCanvas');

  // State
  const state = {
    units: 'metric',
    jointType: 'parallel', // 'parallel', 'woodruff', 'spline'
    fitClass: 'normal',
    // Parallel: Default is (1)F ... DIN 6885: Blatt 1 (index 5)
    keyTypeIndex: 5,
    parallelDiam: 40.0,
    parallelNumKeys: 1,
    parallelLength: 56.0,
    // Woodruff
    woodruffTypeIndex: 2,  // DIN 6888 A
    woodruffDiam: 25.0,
    woodruffKeyIndex: 5,
    woodruffNumKeys: 1,
    // Spline
    splineTypeIndex: 4,    // ISO 14 Medium
    splineSizeIndex: 4,
    splineLength: 60.0
  };

  function updateSelectColor() {
    const sel = document.getElementById('selParallelType');
    if (!sel) return;
    const val = parseInt(sel.value, 10);
    if ([5, 3, 10].includes(val)) {
      sel.style.color = '#059669'; // Ưu tiên cao: Màu xanh lá đậm
      sel.style.fontWeight = 'bold';
    } else if (val === 4) {
      sel.style.color = '#d97706'; // Then mỏng ISO 2491: Màu vàng/cam
      sel.style.fontWeight = 'bold';
    } else {
      sel.style.color = '#111827';
      sel.style.fontWeight = '600';
    }
  }

  // Init dropdowns
  initTypeDropdowns();
  bindEvents();
  updateCalculation();

  function initTypeDropdowns() {
    // 1. Parallel keys standards: Phân nhóm 1-4, đánh số (1) đến (11), tô màu ưu tiên
    const selParallelType = document.getElementById('selParallelType');
    if (selParallelType) {
      selParallelType.innerHTML = '';

      // Định nghĩa 4 nhóm chuẩn hóa theo yêu cầu người dùng
      const groups = [
        {
          label: 'Nhóm 1: Hệ Mét Châu Âu & Quốc Tế (Chế độ ưu tiên)',
          items: [
            { text: '(1)F ... DIN 6885: Blatt 1', val: 5, color: '#10b981', isDefault: true },
            { text: '(2)D ... ISO R773', val: 3, color: '#10b981' },
            { text: '(3)K ... CSN 022562', val: 10, color: '#10b981' },
            { text: '(4)E ... ISO 2491', val: 4, color: '#f59e0b' } // Màu vàng: Then mỏng
          ]
        },
        {
          label: 'Nhóm 2: Hệ Inch Hoa Kỳ (ANSI B17.1)',
          items: [
            { text: '(5)A ... ANSI B17.1 (Preferred)', val: 0, color: '#94a3b8' },
            { text: '(6)B ... ANSI B17.1 (Square)', val: 1, color: '#94a3b8' },
            { text: '(7)C ... ANSI B17.1 (Rectangular)', val: 2, color: '#94a3b8' }
          ]
        },
        {
          label: 'Nhóm 3: Tiêu chuẩn Nhật Bản (JIS)',
          items: [
            { text: '(8)J ... JIS B 1301 (B)', val: 9, color: '#94a3b8' }
          ]
        },
        {
          label: 'Nhóm 4: Tiêu chuẩn Anh (British Standard)',
          items: [
            { text: '(9)G ... BS 46: Part 1 (Square)', val: 6, color: '#94a3b8' },
            { text: '(10)H ... BS 46: Part 1 (Rectangular)', val: 7, color: '#94a3b8' },
            { text: '(11)I ... BS 4235: Part 1', val: 8, color: '#94a3b8' }
          ]
        }
      ];

      groups.forEach(grp => {
        const optgroup = document.createElement('optgroup');
        optgroup.label = grp.label;
        grp.items.forEach(it => {
          const opt = document.createElement('option');
          opt.value = it.val;
          opt.textContent = it.text;
          opt.style.color = it.color;
          opt.style.fontWeight = 'bold';
          if (it.val === state.keyTypeIndex) opt.selected = true;
          optgroup.appendChild(opt);
        });
        selParallelType.appendChild(optgroup);
      });
      updateSelectColor();
    }

    // 2. Woodruff keys standards
    const selWoodruffType = document.getElementById('selWoodruffType');
    if (selWoodruffType) {
      selWoodruffType.innerHTML = '';
      KEYS_DATABASE.T_Key2_Name.forEach((meta, idx) => {
        const opt = document.createElement('option');
        opt.value = idx;
        opt.textContent = meta[0];
        if (idx === state.woodruffTypeIndex) opt.selected = true;
        selWoodruffType.appendChild(opt);
      });
    }

    // 3. Splines standards
    const selSplineType = document.getElementById('selSplineType');
    if (selSplineType) {
      selSplineType.innerHTML = '';
      KEYS_DATABASE.T_spl1_Name.forEach((meta, idx) => {
        const opt = document.createElement('option');
        opt.value = idx;
        opt.textContent = meta[0];
        if (idx === state.splineTypeIndex) opt.selected = true;
        selSplineType.appendChild(opt);
      });
    }
  }

  function bindEvents() {
    // Subsystem tabs
    document.querySelectorAll('.joint-type-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        document.querySelectorAll('.joint-type-btn').forEach(b => b.classList.remove('active'));
        btn.classList.add('active');
        state.jointType = btn.dataset.type;

        // Toggle visibility of input sections
        document.getElementById('secParallelInputs').style.display = state.jointType === 'parallel' ? 'block' : 'none';
        document.getElementById('secWoodruffInputs').style.display = state.jointType === 'woodruff' ? 'block' : 'none';
        document.getElementById('secSplineInputs').style.display = state.jointType === 'spline' ? 'block' : 'none';

        // Toggle results tables
        document.getElementById('secParallelResults').style.display = state.jointType === 'parallel' ? 'block' : 'none';
        document.getElementById('secWoodruffResults').style.display = state.jointType === 'woodruff' ? 'block' : 'none';
        document.getElementById('secSplineResults').style.display = state.jointType === 'spline' ? 'block' : 'none';

        updateCalculation();
      });
    });

    // Units toggle
    const selUnits = document.getElementById('selUnits');
    if (selUnits) {
      selUnits.addEventListener('change', (e) => {
        state.units = e.target.value;
        const isM = state.units === 'metric';
        state.parallelDiam = isM ? 40.0 : 1.5;
        state.woodruffDiam = isM ? 25.0 : 1.0;
        document.getElementById('txtParallelDiam').value = state.parallelDiam;
        document.getElementById('txtWoodruffDiam').value = state.woodruffDiam;
        document.querySelectorAll('.unit-dim').forEach(el => el.textContent = isM ? 'mm' : 'in');
        updateCalculation();
      });
    }

    // Parallel Key controls
    document.getElementById('selParallelType').addEventListener('change', (e) => {
      state.keyTypeIndex = parseInt(e.target.value, 10);
      updateSelectColor();
      updateCalculation();
    });

    document.getElementById('txtParallelDiam').addEventListener('input', (e) => {
      const v = parseFloat(e.target.value.replace(',', '.'));
      if (!isNaN(v) && v > 0) {
        state.parallelDiam = v;
        updateCalculation();
      }
    });

    document.getElementById('selParallelNumKeys').addEventListener('change', (e) => {
      state.parallelNumKeys = parseInt(e.target.value, 10);
      updateCalculation();
    });

    document.getElementById('txtParallelLength').addEventListener('input', (e) => {
      const v = parseFloat(e.target.value.replace(',', '.'));
      if (!isNaN(v) && v > 0) {
        state.parallelLength = v;
        updateCalculation();
      }
    });

    document.getElementById('selFitClass').addEventListener('change', (e) => {
      state.fitClass = e.target.value;
      updateCalculation();
    });

    // Woodruff Key controls
    document.getElementById('selWoodruffType').addEventListener('change', (e) => {
      state.woodruffTypeIndex = parseInt(e.target.value, 10);
      updateCalculation();
    });

    document.getElementById('txtWoodruffDiam').addEventListener('input', (e) => {
      const v = parseFloat(e.target.value.replace(',', '.'));
      if (!isNaN(v) && v > 0) {
        state.woodruffDiam = v;
        updateCalculation();
      }
    });

    document.getElementById('selWoodruffKey').addEventListener('change', (e) => {
      state.woodruffKeyIndex = parseInt(e.target.value, 10);
      updateCalculation();
    });

    // Spline controls
    document.getElementById('selSplineType').addEventListener('change', (e) => {
      state.splineTypeIndex = parseInt(e.target.value, 10);
      updateCalculation();
    });

    document.getElementById('selSplineSize').addEventListener('change', (e) => {
      state.splineSizeIndex = parseInt(e.target.value, 10);
      updateCalculation();
    });

    document.getElementById('txtSplineLength').addEventListener('input', (e) => {
      const v = parseFloat(e.target.value.replace(',', '.'));
      if (!isNaN(v) && v > 0) {
        state.splineLength = v;
        updateCalculation();
      }
    });

    // 3-View Toolbar Buttons
    const viewButtons = [
      { id: 'btnTripleView', view: 'triple' },
      { id: 'btnAssemblyView', view: 'assembly' },
      { id: 'btnShaftView', view: 'shaft' },
      { id: 'btnHubView', view: 'hub' }
    ];

    viewButtons.forEach(btnInfo => {
      const el = document.getElementById(btnInfo.id);
      if (el) {
        el.addEventListener('click', () => {
          viewButtons.forEach(b => {
            const btnEl = document.getElementById(b.id);
            if (btnEl) btnEl.classList.remove('active');
          });
          el.classList.add('active');
          canvas.setDisplayView(btnInfo.view);
        });
      }
    });

    document.getElementById('btnZoomIn').addEventListener('click', () => canvas.zoom(1.2));
    document.getElementById('btnZoomOut').addEventListener('click', () => canvas.zoom(0.8));
    document.getElementById('btnResetView').addEventListener('click', () => canvas.resetView());
    document.getElementById('btnDownloadPNG').addEventListener('click', () => canvas.downloadImage());

    // Accordion global controls
    document.getElementById('btnExpandAll').addEventListener('click', () => {
      document.querySelectorAll('.calc-section').forEach(s => s.classList.remove('collapsed'));
    });
    document.getElementById('btnCollapseAll').addEventListener('click', () => {
      document.querySelectorAll('.calc-section').forEach(s => s.classList.add('collapsed'));
    });

    // Accordion click toggle
    document.querySelectorAll('.section-header').forEach(hdr => {
      hdr.addEventListener('click', () => {
        const sec = hdr.closest('.calc-section');
        if (sec) sec.classList.toggle('collapsed');
      });
    });
  }

  function updateCalculation() {
    let currentData = null;

    if (state.jointType === 'parallel') {
      const res = KeysCalc.calculateParallelKey({
        units: state.units,
        keyTypeIndex: state.keyTypeIndex,
        numKeys: state.parallelNumKeys,
        shaftDiam: state.parallelDiam,
        chosenLength: state.parallelLength,
        fitClass: state.fitClass
      });
      currentData = res;

      // Update DOM
      document.getElementById('outParallelKeyName').textContent = res.keyName;
      document.getElementById('outParallelB').textContent = res.b.toFixed(2);
      document.getElementById('outParallelH').textContent = res.h.toFixed(2);
      document.getElementById('outParallelT1').textContent = res.t1.toFixed(2);
      document.getElementById('outParallelT2').textContent = res.t2.toFixed(2);
      document.getElementById('outParallelD1').textContent = res.d1.toFixed(2);
      document.getElementById('outParallelD2').textContent = res.d2.toFixed(2);
      document.getElementById('outParallelRange').textContent = `${res.Lmin_tab.toFixed(1)} ~ ${res.Lmax_tab.toFixed(1)}`;
      document.getElementById('outParallelLf').textContent = res.Lf_formA.toFixed(2);

      // Tolerances
      document.getElementById('outTolWidth').textContent = res.tolerances.keyWidthTol;
      document.getElementById('outTolHeight').textContent = res.tolerances.keyHeightTol;
      document.getElementById('outTolShaft').textContent = res.tolerances.shaftKeywayTol;
      document.getElementById('outTolHub').textContent = res.tolerances.hubKeywayTol;

      // Summary banner
      document.getElementById('sumJointType').textContent = `Then Bằng (${res.numKeys} then)`;
      document.getElementById('sumStandard').textContent = res.typeName.split('...')[1]?.trim() || res.typeName;
      document.getElementById('sumDimensions').textContent = `${res.b.toFixed(1)} x ${res.h.toFixed(1)} x ${res.chosenL.toFixed(1)}`;
      document.getElementById('sumShaftDiam').textContent = `${res.d.toFixed(1)} mm`;

    } else if (state.jointType === 'woodruff') {
      const res = KeysCalc.calculateWoodruffKey({
        units: state.units,
        woodruffTypeIndex: state.woodruffTypeIndex,
        numKeys: state.woodruffNumKeys,
        shaftDiam: state.woodruffDiam,
        keySizeIndex: state.woodruffKeyIndex
      });
      currentData = res;

      // Populate woodruff key selector
      const selW = document.getElementById('selWoodruffKey');
      if (selW && selW.options.length !== res.allKeys.length) {
        selW.innerHTML = '';
        res.allKeys.forEach(k => {
          const opt = document.createElement('option');
          opt.value = k.index;
          opt.textContent = `${k.name} (b=${k.b.toFixed(1)}, h=${k.h.toFixed(1)})`;
          if (k.index === res.rowIndex) opt.selected = true;
          selW.appendChild(opt);
        });
      }

      // Update DOM
      document.getElementById('outWoodruffKeyName').textContent = res.keyName;
      document.getElementById('outWoodruffB').textContent = res.b.toFixed(2);
      document.getElementById('outWoodruffH').textContent = res.h.toFixed(2);
      document.getElementById('outWoodruffDk').textContent = res.Dk.toFixed(2);
      document.getElementById('outWoodruffL').textContent = res.L.toFixed(2);
      document.getElementById('outWoodruffT1').textContent = res.t1.toFixed(2);
      document.getElementById('outWoodruffD1').textContent = res.d1.toFixed(2);
      document.getElementById('outWoodruffAreaS').textContent = res.areaShaft.toFixed(1);
      document.getElementById('outWoodruffAreaH').textContent = res.areaHub.toFixed(1);

      // Summary
      document.getElementById('sumJointType').textContent = 'Then Bán Nguyệt (Woodruff)';
      document.getElementById('sumStandard').textContent = res.typeName.split('...')[1]?.trim() || res.typeName;
      document.getElementById('sumDimensions').textContent = `${res.b.toFixed(1)} x ${res.h.toFixed(1)} (Ø${res.Dk.toFixed(1)})`;
      document.getElementById('sumShaftDiam').textContent = `${res.d.toFixed(1)} mm`;

    } else if (state.jointType === 'spline') {
      const res = KeysCalc.calculateStraightSpline({
        units: state.units,
        splineTypeIndex: state.splineTypeIndex,
        splineSizeIndex: state.splineSizeIndex,
        chosenLength: state.splineLength
      });
      currentData = res;

      // Populate spline size selector
      const selS = document.getElementById('selSplineSize');
      if (selS && selS.options.length !== res.allSplines.length) {
        selS.innerHTML = '';
        res.allSplines.forEach(s => {
          const opt = document.createElement('option');
          opt.value = s.index;
          opt.textContent = `${s.name} (${s.n} then, D=${s.D.toFixed(1)}, d=${s.d.toFixed(1)})`;
          if (s.index === res.splineSizeIdx) opt.selected = true;
          selS.appendChild(opt);
        });
      }

      // Update DOM
      document.getElementById('outSplineName').textContent = res.splineName;
      document.getElementById('outSplineN').textContent = res.n;
      document.getElementById('outSplineD').textContent = res.D.toFixed(2);
      document.getElementById('outSplined').textContent = res.d.toFixed(2);
      document.getElementById('outSplineB').textContent = res.b.toFixed(2);
      document.getElementById('outSplineS').textContent = res.s.toFixed(2);
      document.getElementById('outSplineH').textContent = res.h.toFixed(2);
      document.getElementById('outSplineDm').textContent = res.dm.toFixed(2);
      document.getElementById('outSplineSlot').textContent = res.slotWidth.toFixed(2);

      document.getElementById('outSplineCentering').textContent = res.tolerances.centeringType;
      document.getElementById('outSplineMinorFit').textContent = res.tolerances.minorDiameterFit;
      document.getElementById('outSplineWidthFit').textContent = res.tolerances.widthFit;

      // Summary
      document.getElementById('sumJointType').textContent = 'Then Hoa Chữ Nhật (Spline)';
      document.getElementById('sumStandard').textContent = res.typeName.split('...')[1]?.trim() || res.typeName;
      document.getElementById('sumDimensions').textContent = `${res.n} then | ${res.D.toFixed(1)}x${res.d.toFixed(1)}x${res.b.toFixed(1)}`;
      document.getElementById('sumShaftDiam').textContent = `D = ${res.D.toFixed(1)} mm`;
    }

    // Send data to Canvas
    canvas.setData(state.jointType, currentData);
  }
});

